import{_ as o,o as i,c as a,ai as c}from"./chunks/framework.Ba-VnP44.js";const I=JSON.parse('{"title":"工业物联网 IIoT · OpenBiz 第九个独立消费者（A 类收官）","description":"","frontmatter":{},"headers":[],"relativePath":"apps/openbiz/iiot.md","filePath":"apps/openbiz/iiot.md"}'),d={name:"apps/openbiz/iiot.md"};function t(n,e,r,p,E,l){return i(),a("div",null,[...e[0]||(e[0]=[c('<h1 id="工业物联网-iiot-·-openbiz-第九个独立消费者-a-类收官" tabindex="-1">工业物联网 IIoT · OpenBiz 第九个独立消费者（A 类收官） <a class="header-anchor" href="#工业物联网-iiot-·-openbiz-第九个独立消费者-a-类收官" aria-label="Permalink to “工业物联网 IIoT · OpenBiz 第九个独立消费者（A 类收官）”">​</a></h1><blockquote><p>现为独立应用 <code>openbiz-iiot-app</code>（<code>E:/8.cangku/for-job/openbiz-iiot-app</code>）：独立后端（端口 18089）+ 独立前端（Vue3/TS）+ 独立数据库 <code>openbiz_iiot</code>。</p></blockquote><blockquote><p>实证：OpenBiz 母仓无 IIoT 域，按 OpenBiz 命名约定自建 <code>openbiz_iiot_*</code> 表，在其多租户基座之上实现「设备 + 告警双状态机 + 统计」最小闭环。<strong>这是 A 类 9 个系统中最后一个试水的，标志 A 类试水全覆盖完成。</strong></p></blockquote><h2 id="复用与自建" tabindex="-1">复用与自建 <a class="header-anchor" href="#复用与自建" aria-label="Permalink to “复用与自建”">​</a></h2><ul><li><strong>复用</strong>：OpenBiz <code>openbiz-saas-core</code> 多租户（TenantContext / TenantService / 自动装配）、RuoYi 登录外壳</li><li><strong>自建</strong>：<code>openbiz_iiot_device</code> / <code>openbiz_iiot_alarm</code> 表 + Mapper / Service / Controller <ul><li>设备状态机：<code>OFFLINE → ONLINE → FAULT → OFFLINE</code>，<code>ONLINE/FAULT → MAINTENANCE → OFFLINE</code>，<code>OFFLINE/ONLINE → DECOMMISSIONED</code>（不可逆终态）</li><li>告警状态机：<code>ACTIVE → ACKNOWLEDGED → RESOLVED</code>，<code>ACTIVE → CANCELLED</code></li></ul></li></ul><h2 id="业务闭环-e2e-已验证" tabindex="-1">业务闭环（E2E 已验证） <a class="header-anchor" href="#业务闭环-e2e-已验证" aria-label="Permalink to “业务闭环（E2E 已验证）”">​</a></h2><p>创建设备(<code>OFFLINE</code>) → 上线(<code>ONLINE</code>) → 建告警(<code>ACTIVE</code>) → 确认(<code>ACKNOWLEDGED</code>) → 解决(<code>RESOLVED</code>)；已解决再确认 / 取消均被 <code>ILLEGAL_TRANSITION</code> 拒绝。独立路径报故障(<code>FAULT</code>) → 维护(<code>MAINTENANCE</code>) → 结束维护(<code>OFFLINE</code>) → 再上线(<code>ONLINE</code>) → 退役(<code>DECOMMISSIONED</code>)；退役后再上线被拒。统计接口 <code>GET /api/iiot/stats</code> 返回设备 / 告警各状态数量。</p><h2 id="工程位置" tabindex="-1">工程位置 <a class="header-anchor" href="#工程位置" aria-label="Permalink to “工程位置”">​</a></h2><p><code>E:/8.cangku/for-job/openbiz-iiot-app</code>（含 README 与 E2E 脚本，端口 18089）</p><h2 id="价值" tabindex="-1">价值 <a class="header-anchor" href="#价值" aria-label="Permalink to “价值”">​</a></h2><p>与工单 / MES / PMS / CRM / ERP / EAM / OA / BPM 共同坐实「百套流水线」可复制。至此 <strong>A 类 9 个系统（工单/MES/PMS/CRM/ERP/EAM/OA/BPM/IIoT）全部以独立消费者方式跑通</strong>，OpenBiz 作为 A 类统一底座的结论获充分实证。后续可叠加 MQTT/Modbus 接入、时序库、设备影子与规则引擎。</p><hr><p>上一级：<a href="/my-vitepress-site/apps/openbiz/">OpenBiz 试水实证</a></p>',13)])])}const N=o(d,[["render",t]]);export{I as __pageData,N as default};
